import React, { useState } from 'react';

function SeatScreen({ showtime, movie, seats, bookings, onBookingSuccess, onBack }) {
  const [selectedSeats, setSelectedSeats] = useState([]);

  const isSeatBooked = (seatId) => bookings.some(b => b.showtime_id === showtime.id && b.seat_id === seatId);

  const handleSeatClick = (seat) => {
    if (isSeatBooked(seat.id)) return;
    if (selectedSeats.includes(seat.id)) {
      setSelectedSeats(selectedSeats.filter(id => id !== seat.id));
    } else {
      setSelectedSeats([...selectedSeats, seat.id]);
    }
  };

  const handleConfirm = () => {
    if (selectedSeats.length === 0) {
      alert("Vui lòng chọn ít nhất 1 ghế trước khi bấm xác nhận!");
      return;
    }
    alert(`🎉 Đặt vé thành công! Bạn đã đặt ${selectedSeats.length} ghế.`);
    
    const newBookings = selectedSeats.map(id => ({
      id: Math.random(),
      showtime_id: showtime.id,
      seat_id: id
    }));
    
    onBookingSuccess(newBookings);
    setSelectedSeats([]);
  };

  return (
    <div>
      <button className="btn mb-4 fw-bold text-white border-0" style={{ background: 'linear-gradient(135deg, #7c3aed 0%, #a855f7 100%)' }} onClick={onBack}>⬅ Quay lại suất chiếu</button>
      
      <div className="row">
        <div className="col-md-8 mb-4">
          <div className="card p-4 shadow-sm border-0 text-center bg-white">
            <div className="text-white py-2 mb-5 rounded fw-bold shadow-sm" style={{ letterSpacing: '4px', background: 'linear-gradient(135deg, #7c3aed 0%, #ec4899 100%)' }}>🎬 MÀN HÌNH CHIẾU</div>
            
            <div className="d-flex flex-wrap justify-content-center gap-3 mx-auto" style={{ maxWidth: '300px' }}>
              {seats.map(seat => {
                const booked = isSeatBooked(seat.id);
                const selected = selectedSeats.includes(seat.id);
                
                let btnClass = "btn fw-bold";
                let btnStyle = { width: '65px', height: '55px', backgroundColor: '#f3f4f6', color: '#6b7280', border: '1px solid #e5e7eb' };
                if (booked) { btnClass = "btn fw-bold disabled text-white"; btnStyle = { ...btnStyle, backgroundColor: '#ec4899', color: 'white', border: 'none' }; }
                if (selected) { btnClass = "btn fw-bold text-white shadow"; btnStyle = { ...btnStyle, backgroundColor: '#fbbf24', color: '#78350f', border: 'none' }; }

                return (
                  <button key={seat.id} className={btnClass} style={btnStyle} onClick={() => handleSeatClick(seat)}>
                    {seat.seat_number}
                  </button>
                );
              })}
            </div>

            <div className="d-flex justify-content-center gap-4 mt-5 border-top pt-3 small fw-bold text-secondary">
              <div><span className="badge me-1" style={{width:'15px', height:'15px', backgroundColor: '#f3f4f6'}}> </span> Trống</div>
              <div><span className="badge me-1" style={{width:'15px', height:'15px', backgroundColor: '#fbbf24'}}> </span> Đang chọn</div>
              <div><span className="badge me-1" style={{width:'15px', height:'15px', backgroundColor: '#ec4899'}}> </span> Đã đặt</div>
            </div>
          </div>
        </div>

        <div className="col-md-4">
          <div className="card p-4 shadow-sm border-0 bg-white sticky-top" style={{ top: '20px' }}>
            <h4 className="fw-bold border-bottom pb-2 text-dark">Thông Tin Đặt Vé</h4>
            <div className="mb-3 mt-2">Phim: <strong className="text-danger fs-5 d-block">{movie.title}</strong></div>
            <div className="mb-2">Suất Chiếu: <strong className="text-dark">{showtime.show_time} | {showtime.show_date}</strong></div>
            <div className="mb-4">Số lượng ghế: <strong className="badge bg-primary fs-6">{selectedSeats.length} ghế</strong></div>
            
            <div className="border-top pt-3 d-flex justify-content-between align-items-center">
              <span className="fw-bold text-secondary">Tổng Tiền:</span>
              <h3 className="fw-bold text-danger m-0">{(selectedSeats.length * showtime.ticket_price).toLocaleString()}đ</h3>
            </div>
            
            <button className="btn btn-success w-100 fw-bold mt-4 py-3 fs-5 shadow" onClick={handleConfirm}>XÁC NHẬN ĐẶT VÉ</button>
          </div>
        </div>
      </div>
    </div>
  );
}

export default SeatScreen;
